-- A collection's id becomes a cuid2, and it gains an optional `ref_id` for its web address.
--
-- **`id` is a cuid2** — 24 characters, a lowercase letter then lowercase letters and digits —
-- generated by the app (`cuid2::create_id`) when a collection is named. It was an integer
-- identity, which put a guessable, enumerable count in every URL. Existing rows get an id of
-- the same shape here; `collection_posts.collection_id` follows its collection.
--
-- **`ref_id` is the address**: `/collections/<ref_id>` when set, `/collections/<id>`
-- otherwise. Optional, unique, and changeable from the app — so an old address stops working
-- when it is changed. Lowercase letters, digits and single hyphens; it may not have the shape of
-- a cuid2, so a URL segment can never mean two different collections.

-- One-time generator for the existing rows: same shape as a cuid2, gone with the session.
create function pg_temp.cuid2_like() returns text language sql volatile as $$
  select chr(97 + floor(random() * 26)::int)
      || string_agg(substr('0123456789abcdefghijklmnopqrstuvwxyz', floor(random() * 36)::int + 1, 1), '')
    from generate_series(1, 23)
$$;

alter table collections add column new_id text;
update collections set new_id = pg_temp.cuid2_like();

alter table collection_posts add column new_collection_id text;
update collection_posts p set new_collection_id = c.new_id from collections c where c.id = p.collection_id;

-- The posts' side: drop the integer link, put the text one in its place.
alter table collection_posts drop constraint collection_posts_collection_id_fkey;
drop index collection_posts_collection_idx;
alter table collection_posts drop column collection_id;
alter table collection_posts rename column new_collection_id to collection_id;
alter table collection_posts alter column collection_id set not null;

-- The collections' side.
drop index collections_updated_idx;
alter table collections drop constraint collections_pkey;
alter table collections drop column id;
alter table collections rename column new_id to id;
alter table collections alter column id set not null;
alter table collections add constraint collections_pkey primary key (id);
alter table collections add constraint collections_id_format check (id ~ '^[a-z][a-z0-9]{23}$');
create index collections_updated_idx on collections (updated_at desc, id desc);

-- Still no `on delete cascade`: a collection that holds images cannot be deleted.
alter table collection_posts
  add constraint collection_posts_collection_id_fkey
  foreign key (collection_id) references collections (id);
create index collection_posts_collection_idx on collection_posts (collection_id, id desc);

alter table collections add column ref_id text;
alter table collections add constraint collections_ref_id_format check (
  length(ref_id) <= 64
  and ref_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
  and ref_id !~ '^[a-z][a-z0-9]{23}$'
);
create unique index collections_ref_id_key on collections (ref_id);
